type syscall struct {
	sysno uint64
}

// Name implements subcommands.Command.
func (*syscall) Name() string {
	return "syscall"
}

// Synopsis implements subcommands.Command.Synopsis.
func (*syscall) Synopsis() string {
	return "syscall makes a syscall"
}

// Usage implements subcommands.Command.Usage.
func (*syscall) Usage() string {
	return "syscall <flags> [arg1 arg2...]"
}

// SetFlags implements subcommands.Command.SetFlags.
func (s *syscall) SetFlags(f *flag.FlagSet) {
	f.Uint64Var(&s.sysno, "syscall", 0, "syscall to call")
}

// Execute implements subcommands.Command.
func (s *syscall) Execute(ctx context.Context, f *flag.FlagSet, _ ...any) subcommands.ExitStatus {
	numArgs := f.NArg()
	if err := validateSyscallArguments(numArgs); err != nil {
		fmt.Println(err)
		return subcommands.ExitUsageError
	}

	syscallArgs := make([]uintptr, numArgs)
	if err := setSyscallArguments(f, syscallArgs); err != nil {
		fmt.Println(err)
		return subcommands.ExitUsageError
	}

	errno := makeSyscall(s.sysno, syscallArgs)
	if errno != 0 {
		fmt.Printf("syscall(%d) failed: %v\n", s.sysno, errno)
		return subcommands.ExitFailure
	}
	fmt.Printf("syscall(%d) success\n", s.sysno)
	return subcommands.ExitSuccess
}

func validateSyscallArguments(numArgs int) error {
	const maxSyscallArgs = 6
	if numArgs > maxSyscallArgs {
		return fmt.Errorf("number of syscall arguments not supported: %d (max is %d)", numArgs, maxSyscallArgs)
	}
	return nil
}

func setSyscallArguments(f *flag.FlagSet, syscallArgs []uintptr) error {
	for i := 0; i < f.NArg(); i++ {
		uintArg, err := strconv.ParseUint(f.Arg(i), 10, 64)
		if err != nil {
			return fmt.Errorf("not an integer: %q", f.Arg(i))
		}
		syscallArgs[i] = uintptr(uintArg)
	}
	return nil
}

func makeSyscall(sysno uint64, args []uintptr) sys.Errno {
	var errno sys.Errno
	switch len(args) {
	case 0:
		_, _, errno = sys.Syscall(uintptr(sysno), 0, 0, 0)
	case 1:
		_, _, errno = sys.Syscall(uintptr(sysno), args[0], 0, 0)
	case 2:
		_, _, errno = sys.Syscall(uintptr(sysno), args[0], args[1], 0)
	case 3:
		_, _, errno = sys.Syscall(uintptr(sysno), args[0], args[1], args[2])
	case 4:
		_, _, errno = syscall.Syscall6(uintptr(sysno), args[0], args[1], args[2], args[3], 0, 0)
	case 5:
		_, _, errno = syscall.Syscall6(uintptr(sysno), args[0], args[1], args[2], args[3], args[4], 0)
	case 6:
		_, _, errno = syscall.Syscall6(uintptr(sysno), args[0], args[1], args[2], args[3], args[4], args[5])
	}
	return errno
}
```

