const (
	maxSyscallFilterInstructions = 1 << 15
	uncacheableBPFAction        = linux.SECCOMP_RET_ACTION_FULL
)

// taskSeccomp holds seccomp-related data for a Task.
type taskSeccomp struct {
	filters         []bpf.Program
	cache           [sentry.MaxSyscallNum + 1]linux.BPFAction
	cacheAuditNumber uint32
}

// copy creates and returns a deep copy of the taskSeccomp instance.
func (ts *taskSeccomp) copy() *taskSeccomp {
	return &taskSeccomp{
		filters:         append([]bpf.Program{}, ts.filters...),
		cache:           ts.cache,
		cacheAuditNumber: ts.cacheAuditNumber,
	}
}

// dataAsBPFInput converts SeccompData to a serialized BPF input.
func dataAsBPFInput(t *Task, d *linux.SeccompData) bpf.Input {
	buffer := t.CopyScratchBuffer(d.SizeBytes())
	d.MarshalUnsafe(buffer)
	return buffer[:d.SizeBytes()]
}

// seccompSiginfo generates SignalInfo for seccomp syscall signals.
func seccompSiginfo(t *Task, errno, sysno int32, ip hostarch.Addr) *linux.SignalInfo {
	signalInfo := &linux.SignalInfo{
		Signo: int32(linux.SIGSYS),
		Errno: errno,
		Code:  linux.SYS_SECCOMP,
	}
	signalInfo.SetCallAddr(uint64(ip))
	signalInfo.SetSyscall(sysno)
	signalInfo.SetArch(t.SyscallTable().AuditNumber)
	return signalInfo
}

// checkSeccompSyscall validates seccomp filters prior to syscall execution.
func (t *Task) checkSeccompSyscall(sysno int32, args arch.SyscallArguments, ip hostarch.Addr) linux.BPFAction {
	// Default action is to allow.
	action := t.evaluateSyscallFilters(sysno, args, ip) & linux.SECCOMP_RET_ACTION

	switch action {
	case linux.SECCOMP_RET_TRAP:
		t.SendSignal(seccompSiginfo(t, int32(action.Data()), sysno, ip))
		t.Arch().SetReturn(uintptr(sysno))
		return action

	case linux.SECCOMP_RET_ERRNO:
		t.Arch().SetReturn(-uintptr(action.Data()))
		return action

	case linux.SECCOMP_RET_TRACE:
		if !t.ptraceSeccomp(action.Data()) {
			t.Arch().SetReturn(-uintptr(unix.ENOSYS))
			return linux.SECCOMP_RET_ERRNO
		}

	case linux.SECCOMP_RET_ALLOW:
		return action // Allow execution of the syscall.

	case linux.SECCOMP_RET_KILL_THREAD:
		return linux.SECCOMP_RET_KILL_THREAD // terminate the thread
	}

	return linux.SECCOMP_RET_KILL_THREAD // Default fallback
}

func (t *Task) evaluateSyscallFilters(sysno int32, args arch.SyscallArguments, ip hostarch.Addr) uint32 {
	ret := uint32(linux.SECCOMP_RET_ALLOW)
	ts := t.seccomp.Load()
	if ts == nil {
		return ret
	}

	if t.isCacheValid(ts, sysno) {
		if cached := ts.cache[sysno]; cached != uncacheableBPFAction {
			return uint32(cached)
		}
	}

	data := t.prepareSeccompData(sysno, ts.cacheAuditNumber, ip, args)
	input := dataAsBPFInput(t, &data)

	for i := len(ts.filters) - 1; i >= 0; i-- {
		result, err := bpf.Exec[bpf.NativeEndian](ts.filters[i], input)
		if err != nil {
			t.Debugf("seccomp-bpf filter %d returned error: %v", i, err)
			result = uint32(linux.SECCOMP_RET_KILL_THREAD)
		}
		ret = t.minAction(ret, result)
	}

	return ret
}

